const paths={arrow:'<path d="M5 12h14m-6-6 6 6-6 6"/>',back:'<path d="m14 6-6 6 6 6"/>',chevron:'<path d="m9 6 6 6-6 6"/>',coffee:'<path d="M4 9h13v7a4 4 0 0 1-4 4H8a4 4 0 0 1-4-4V9Zm13 1h2a3 3 0 1 1 0 6h-2M7 3v3m4-3v3m4-3v3"/>',gym:'<path d="M3 8v8m3-10v12m12-12v12m3-10v8M6 12h12"/>',padel:'<ellipse cx="14" cy="9" rx="6" ry="7" transform="rotate(35 14 9)"/><path d="m9 14-6 7m4-9 5 4M12 6h.01M15 6h.01M11 9h.01M14 9h.01M17 9h.01M11 12h.01M14 12h.01"/>',signup:'<path d="M13 3H5a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h14M7 7h5M7 11h3M12 17l1-4 7-7 3 3-7 7-4 1Z"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M7 3v4m10-4v4M3 11h18M7 15h.01M12 15h.01M17 15h.01M7 18h.01M12 18h.01"/>',event:'<rect x="3" y="5" width="16" height="16" rx="2"/><path d="M7 3v4m8-4v4M3 10h16M11 13v5m-2.5-2.5h5"/>',class:'<circle cx="12" cy="8" r="2"/><path d="M5 4h14M4 2v4m16-4v4M7 6l3 6h4l3-6M10 12l-4 9m8-9 4 9M2 14l3 3m17-3-3 3"/>',pin:'<path d="M19 10c0 5-7 11-7 11S5 15 5 10a7 7 0 1 1 14 0Z"/><circle cx="12" cy="10" r="2"/>',check:'<path d="m5 12 4 4L19 6"/>',shield:'<path d="m12 3 8 3v6c0 5-8 9-8 9s-8-4-8-9V6l8-3Z"/><path d="m8 12 3 3 5-6"/>',info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6m0-10h.01"/>',home:'<path d="m3 10 9-7 9 7M5 9v12h5v-6h4v6h5V9"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 6v6l4 2"/>'};
const icon=(name)=>`<svg viewBox="0 0 24 24" aria-hidden="true">${paths[name]||paths.arrow}</svg>`;
const appHeader=()=>`<header class="top"><a href="#hub" aria-label="Midpoint Hub home"><img src="assets/hub-logo.png" alt="Midpoint Hub"></a><a class="mark" href="#hub" aria-label="Choose a destination">${icon('home')}</a></header>`;
const back=(url,label)=>`<a class="breadcrumb" href="#${url}">${icon('back')} ${label}</a>`;
const footer=()=>`<footer class="footer"><b>All at Midpoint.</b><br>162 Tonetti Street, Halfway House, Midrand<br><a href="#hub">FOND · Gym · Padel</a></footer>`;
const primary=(url,label,secondary=false)=>`<a class="${secondary?'secondary':'primary'}" href="${url}">${label}${icon('arrow')}</a>`;
const note=(title,copy,ico='info')=>`<section class="note">${icon(ico)}<div><h3>${title}</h3><p>${copy}</p></div></section>`;
const badge=(url,label,ico,brand)=>`<a class="round-action" href="${url}" ${url.startsWith("https:")?'target="_blank" rel="noopener"':''}><span class="badge"><small>Midpoint ${brand}</small>${icon(ico)}</span><span>${label}</span></a>`;
const intro=(label,title,copy)=>`<section class="intro"><span class="eyebrow">${label}</span><h1>${title}</h1><p>${copy}</p></section>`;
function hub(){return `${appHeader()}<section class="hub-hero"><span class="eyebrow">WELCOME TO YOUR MIDPOINT</span><h1>Your day.<br>All at Midpoint.</h1><p>Your coffee, your next class, your time on court. All in one place.</p></section><div class="section-label">WHERE WOULD YOU LIKE TO GO?</div><nav class="destinations" aria-label="Choose a destination"><a class="destination fond" style="--service:#d86432" href="https://fond.mid-point.co.za/" target="_blank" rel="noopener"><span class="round-icon">${icon('coffee')}</span><div><h2>fond.</h2><p>Coffee, good food &amp; rewards</p></div>${icon('arrow').replace('<svg','<svg class="forward"')}</a><a class="destination gym" style="--service:#003c35" href="#gym"><span class="round-icon">${icon('gym')}</span><div><span class="service-label">MIDPOINT</span><h2>Gym</h2><p>Find your everyday energy</p></div>${icon('arrow').replace('<svg','<svg class="forward"')}</a><a class="destination padel" style="--service:#2458cb" href="#padel"><span class="round-icon">${icon('padel')}</span><div><span class="service-label">MIDPOINT</span><h2>Padel</h2><p>Meet you on the court</p></div>${icon('arrow').replace('<svg','<svg class="forward"')}</a></nav><div class="hub-foot"><span>${icon('pin')} Midpoint · Midrand</span><span>A little more to your day.</span></div>`}
function landing(service){let gym=service==='gym';return `${appHeader()}${back('hub','Midpoint Hub')}<div class="photo"><img src="assets/${gym?'gym':'padel'}.jpg.png" alt="${gym?'Midpoint Gym training floor':'Midpoint rooftop padel courts'}"><span class="photo-label">${gym?'MOVE & RECHARGE':'PLAY & UNWIND'}</span></div><section class="landing-title"><span class="eyebrow">MIDPOINT ${gym?'GYM':'PADEL'}</span><h1>${gym?'Make time<br>for your strength.':'A better way<br>to end your day.'}</h1><p>${gym?'A great workout, a fresh start. Right here on the estate.':'Good rallies. Great company. Your next game starts here.'}</p></section><nav class="round-actions" aria-label="${service} actions">${gym?badge('#gym-signup','Sign up','signup','Gym')+badge('#gym-events','Join an event','event','Gym')+badge('#gym-classes','Join a class','class','Gym'):badge('#padel-signup','Tenant signup','signup','Padel')+badge('https://playtomic.com/','Book a court','padel','Padel')+badge('#padel-events','Join an event','event','Padel')}</nav>${gym?note('Your membership starts here','Send us your details, then visit the gym. Our team will complete your Itensity registration, finalise payment and set up your gym access.','shield'):note('A Midpoint tenant? Let’s get you playing.','Request your tenant setup. Our team will help register you on Playtomic and send the details you need to get started.','shield')}<div class="provider">${gym?'Membership & gym access':'Court bookings'} <b>${gym?'Itensity':'Playtomic'}</b></div>${footer()}`}
const field=(label,type,placeholder,extra='')=>`<label>${label}<input type="${type}" placeholder="${placeholder}" ${extra}></label>`;
function signup(service){const gym=service==='gym';return `${appHeader()}${back(service,`Midpoint ${gym?'Gym':'Padel'}`)}${intro(gym?'YOUR NEXT CHAPTER':'FOR MIDPOINT TENANTS',gym?'Let’s get<br>you moving.':'Let’s get<br>you on court.',gym?'Leave your details and we’ll help you get started. Your membership is completed in person at the gym.':'Tell us where you work at Midpoint. We’ll verify your tenant details and help set you up on Playtomic.')}<div class="stepper"><b>1</b> Your details <i></i><b class="later">2</b> ${gym?'Visit the gym':'Staff setup'}</div><form class="form" data-service="${service}"><div class="field-row">${field('First name','text','e.g. Alex','autocomplete="given-name" required')}${field('Surname','text','e.g. Taylor','autocomplete="family-name" required')}</div>${field('Email address','email','alex@example.com','autocomplete="email" required')}${field('Mobile number','tel','e.g. 082 000 0000','autocomplete="tel" required')}<label>${gym?'ID or passport number':'Company / tenant name'}<input type="text" placeholder="${gym?'Your ID or passport number':'Company registered at Midpoint'}" required>${gym?'<span class="helper">Our gym team will verify this when you visit. Use dummy details in this design preview.</span>':''}</label>${gym?`<label>Are you based at Midpoint?<select><option>Select an option</option><option>Yes, I work at Midpoint</option><option>No, I am visiting</option></select></label>${field('Company / tenant name <span class="optional">· if applicable</span>','text','Your company name')}`:`${field('Building / unit','text','e.g. Block B, Unit 12','required')}<label>Do you already use Playtomic?<select id="playtomic-account"><option>No, I need help getting started</option><option>Yes, I already have an account</option></select><span class="helper">If you already have an account, use its email address above so our team can help with your existing profile.</span></label>`}<label class="check"><input type="checkbox" required><span>I agree that Midpoint may contact me about this ${gym?'membership':'tenant signup'} request and use my details to assist with ${gym?'gym':'Playtomic'} registration.</span></label><button class="primary" type="submit">${gym?'Send signup request':'Request tenant setup'}${icon('arrow')}</button><p class="mini">Design preview only · No details are saved or sent.</p></form>${note(gym?'Finish at the gym':'What happens next',gym?'Our staff will help you choose your membership, register you on Itensity and finalise payment. Gym access is activated after that visit.':'Our staff will verify your tenant details and contact you with your Playtomic setup instructions. This request does not book a court.')}${footer()}`}
function confirmation(service){const gym=service==='gym';return `${appHeader()}${back(service,`Midpoint ${gym?'Gym':'Padel'}`)}<div class="inline-demo">SAMPLE CONFIRMATION · No request has been sent</div><section class="success"><div class="tick">${icon('check')}</div><span class="eyebrow">${gym?'YOUR NEXT STEP':'YOU’RE ON YOUR WAY'}</span><h1>${gym?'See you<br>at the gym.':'Next stop:<br>the court.'}</h1><p>${gym?'Thanks for your interest in Midpoint Gym. Here’s how we’ll get your membership ready.':'Our team will help get your tenant profile ready for Playtomic.'}</p></section><ol class="steps">${gym?`<li><div><strong>Come through to reception</strong><p>Bring your ID or passport and speak to the Midpoint Gym team.</p></div></li><li><div><strong>We’ll register you on Itensity</strong><p>Choose your membership with our staff and complete the required registration details.</p></div></li><li><div><strong>Finalise payment & access</strong><p>Once everything is confirmed, our team will activate your gym entrance access.</p></div></li>`:`<li><div><strong>We’ll confirm your tenant details</strong><p>Our team checks your company and building information.</p></div></li><li><div><strong>We’ll help with Playtomic setup</strong><p>We’ll use your existing profile where possible, or help you get started with a new one.</p></div></li><li><div><strong>Look out for your details</strong><p>We’ll contact you using your email or mobile with the next steps. Court bookings follow on Playtomic.</p></div></li>`}</ol><div class="button-stack">${primary(gym?'#gym-classes':'#padel-events',gym?'Explore the class calendar':'Explore padel events')}${primary('#hub','Back to Midpoint Hub',true)}</div>${footer()}`}
let calMonth=8,calYear=2026,selectedDay=29;
const schedules={ 'gym-classes':[{day:29,time:'06:30',title:'Strength & conditioning',meta:'45 min · Gym floor',type:'Class',copy:'Build strength with a guided full-body session. Suitable for a range of fitness levels.'},{day:29,time:'12:15',title:'Lunchtime mobility',meta:'30 min · Studio',type:'Class',copy:'Reset your posture and release tension with a short mobility session.'},{day:30,time:'17:15',title:'After-work circuit',meta:'45 min · Gym floor',type:'Class',copy:'Finish the working day with an energising guided circuit.'}], 'gym-events':[{day:29,time:'17:30',title:'Meet the trainers',meta:'60 min · Midpoint Gym',type:'Community',copy:'Meet the gym team, explore the space and find out about getting started.'},{day:30,time:'12:00',title:'Wellness at work',meta:'45 min · Midpoint Gym',type:'Workshop',copy:'Practical ways to bring more movement into the working day.'}], 'padel-events':[{day:29,time:'17:00',title:'Tenant social padel',meta:'90 min · Rooftop courts',type:'Social play',copy:'Meet other Midpoint tenants for a relaxed social session on the rooftop courts.'},{day:30,time:'17:30',title:'New to padel?',meta:'60 min · Rooftop courts',type:'Introduction',copy:'An introduction to the court, the rules and your first rally.'}]};
function calendar(id){const padel=id.startsWith('padel'),classes=id.endsWith('classes');return `${appHeader()}${back(padel?'padel':'gym',padel?'Midpoint Padel':'Midpoint Gym')}<section class="calendar-heading"><span class="eyebrow">${padel?'MEET. PLAY. REPEAT.':'MAKE SPACE FOR MOVEMENT'}</span><h1>${classes?'Find your next class.':'Something to join.'}</h1><p>${classes?'Make a little time for yourself.':'Good things happen when we get together.'}</p></section>${padel?'':`<nav class="calendar-tabs"><a href="#gym-classes" class="${classes?'active':''}">Classes</a><a href="#gym-events" class="${!classes?'active':''}">Events</a></nav>`}<div class="calendar" id="calendar"></div><section class="schedule"><div class="schedule-title"><h2 id="selected-date"></h2><span class="sample">SAMPLE SCHEDULE</span></div><div id="events"></div><p class="calendar-help">${padel?'Court reservations are completed on Playtomic.':'Membership and participation are confirmed by the gym team.'} Dates and times shown here are examples for design review.</p></section>${note(padel?'New tenant? Start here.':'Not a member yet?',padel?'Send your tenant signup request and our staff will help you get set up on Playtomic.':'Send a signup request, then visit the gym to complete your Itensity registration and payment.')}<div class="button-stack">${primary(padel?'#padel-signup':'#gym-signup',padel?'Tenant signup':'Start your signup',true)}</div>${footer()}`}
function updateCalendar(id){const date=new Date(calYear,calMonth,selectedDay),first=(new Date(calYear,calMonth,1).getDay()+6)%7,days=new Date(calYear,calMonth+1,0).getDate();const entries=calYear===2026&&calMonth===8?schedules[id]:[];
document.querySelector('#calendar').innerHTML=`<div class="month-head"><button data-month="-1" aria-label="Previous month">${icon('back')}</button><span>${date.toLocaleDateString('en-ZA',{month:'long',year:'numeric'})}</span><button data-month="1" aria-label="Next month">${icon('chevron')}</button></div><div class="weekdays">${['M','T','W','T','F','S','S'].map(d=>`<span>${d}</span>`).join('')}</div><div class="dates">${'<span></span>'.repeat(first)}${Array.from({length:days},(_,i)=>`<button data-day="${i+1}" aria-label="${i+1} ${date.toLocaleDateString('en-ZA',{month:'long',year:'numeric'})}" aria-pressed="${i+1===selectedDay}" class="${i+1===selectedDay?'selected ':''}${entries.some(e=>e.day===i+1)?'has-event':''}">${i+1}</button>`).join('')}</div>`;
document.querySelector('#selected-date').textContent=date.toLocaleDateString('en-ZA',{weekday:'short',day:'numeric',month:'short'});const items=entries.filter(e=>e.day===selectedDay);document.querySelector('#events').innerHTML=items.length?items.map(e=>`<button class="event" data-event="${schedules[id].indexOf(e)}"><time>${e.time}</time><div class="event-copy"><span class="pill">${e.type}</span><h3>${e.title}</h3><p>${e.meta}</p></div>${icon('chevron')}</button>`).join(''):'<p class="empty">No sample sessions on this date. Try 29 or 30 September.</p>';
}
function openEvent(id,index){const e=schedules[id][index],padel=id.startsWith('padel');const d=document.querySelector('#detail');d.innerHTML=`<button class="close" aria-label="Close details">${icon('back')}</button><span class="sample">SAMPLE ${e.type.toUpperCase()}</span><h2>${e.title}</h2><p>${e.copy}</p><p class="detail-meta">${e.day} September 2026 · ${e.time}<br>${e.meta}</p><p>${padel?'Register your interest with the team. Event participation and any booking details will be confirmed separately.':'Ask the gym team to confirm your place. Membership and availability are checked before participation.'}</p><button class="primary" data-interest>I'm interested ${icon('arrow')}</button><p class="helper" style="text-align:center;margin-top:12px">Preview only · This does not reserve a place.</p>`;d.showModal()}
function render(){const id=location.hash.slice(1)||'hub';document.body.className=id.startsWith('padel')?'padel':'';const app=document.querySelector('#app');if(id==='hub')app.innerHTML=hub();else if(id==='gym'||id==='padel')app.innerHTML=landing(id);else if(id.endsWith('-signup'))app.innerHTML=signup(id.split('-')[0]);else if(id.endsWith('-confirm'))app.innerHTML=confirmation(id.split('-')[0]);else if(schedules[id]){app.innerHTML=calendar(id);calMonth=8;calYear=2026;selectedDay=29;updateCalendar(id)}else{location.hash='hub';return}document.querySelector('#detail').close();window.scrollTo(0,0);parent.postMessage({screen:id},location.origin);document.title=`Midpoint Hub · ${id.replaceAll('-',' ')}`}
window.addEventListener('hashchange',render);document.addEventListener('submit',e=>{if(e.target.matches('.form')){e.preventDefault();location.hash=e.target.dataset.service+'-confirm'}});document.addEventListener('click',e=>{const m=e.target.closest('[data-month]'),day=e.target.closest('[data-day]'),event=e.target.closest('[data-event]');const id=location.hash.slice(1);if(m){calMonth+=Number(m.dataset.month);if(calMonth<0){calMonth=11;calYear--}if(calMonth>11){calMonth=0;calYear++}selectedDay=1;updateCalendar(id)}if(day){selectedDay=Number(day.dataset.day);updateCalendar(id)}if(event)openEvent(id,Number(event.dataset.event));if(e.target.closest('.close'))document.querySelector('#detail').close();if(e.target.closest('[data-interest]')){document.querySelector('#detail').innerHTML=`<button class="close" aria-label="Close details">${icon('back')}</button><span class="sample">PREVIEW ONLY</span><h2>We’ll help<br>you join in.</h2><p>The proposed flow sends your interest to the ${id.startsWith('padel')?'Padel':'Gym'} team to confirm availability and next steps.</p><p>No request has been sent and no place is reserved in this prototype.</p><button class="secondary close-dialog">Back to the calendar</button>`}if(e.target.closest('.close-dialog'))document.querySelector('#detail').close()});render();
